using QuantForge.Core;namespace QuantForge.Core.ArchitectureTests;public sealed class AndroidTestChecklistFileStoreTests{[Fact]public void Checklist_round_trips(){var m=ReleaseValidationMatrixRules.Create(true,null,null);var v=AndroidTestChecklistRules.Create(ReleaseCandidateSummaryRules.Create("1","1","c","t",m,m));var p=Path.GetTempFileName();try{var s=new AndroidTestChecklistFileStore(p);s.Save(v);Assert.Equal(v.Count,s.Load().Count);}finally{File.Delete(p);}}}
